#!/usr/bin/env python3
import collections,datetime,hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
features=json.loads((ROOT/'inventory.json').read_text());coverage=json.loads((ROOT/'coverage.json').read_text());photos=json.loads((ROOT/'selected-captures.json').read_text())
functional=json.loads((ROOT/'logs/qml-functional-results.json').read_text())
widgets=json.loads((ROOT/'logs/widgets-checks.json').read_text())
extra=json.loads((ROOT/'logs/qml-additional-checks.json').read_text());shell=json.loads((ROOT/'logs/qml-native-shell-checks.json').read_text())
qtest={}
for name in ['qml-unit-tests','qml-quick-tests','widgets-qt-tests']:
    text=(ROOT/'logs'/f'{name}.log').read_text()
    totals=[tuple(map(int,m)) for m in re.findall(r'Totals: (\d+) passed, (\d+) failed, (\d+) skipped',text)]
    qtest[name]=dict(zip(['passed','failed','skipped'],map(sum,zip(*totals))))
    qtest[name]['exit_code']=int((ROOT/'logs'/f'{name}.exit').read_text())
summary={'date':'2026-10-08','groups':len(features),'criteria':len(coverage),'selected_captures':len(photos),'captures_by_application':dict(collections.Counter(p['application'] for p in photos)),'qml_functional':dict(collections.Counter(r['status'] for r in functional)),'qtest':qtest,'widgets_live_assertions':dict(collections.Counter(r['status'] for r in widgets)),'qml_additional_assertions':dict(collections.Counter(r['status'] for r in extra)),'qml_native_shell_assertions':dict(collections.Counter(r['status'] for r in shell)),'criteria_statuses':{app:dict(collections.Counter(r[app] for r in coverage)) for app in ['widgets','qml']}}
(ROOT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# GUI feature acceptance evidence','','Evidence collected **October 8, 2026** for the [supported-feature comparison](../bitcoin-core-gui-supported-features.md). This pack contains **34 feature-group pages**, **203 criterion sections**, and **'+str(len(photos))+' selected, original application screenshots**. Each criterion links visible evidence, implementation modules, relevant automated tests, and remaining limits.','',
'**This is an evidence pack for review, not a declaration that every feature is complete.** All acceptance checkboxes remain unset. Some criteria have only source or related-test evidence; missing GUI workflows and untested variants are called out individually.','',
'**Runtime finding:** 33 of 34 existing QML functional scripts passed. `qml_test_send_create` fails when returning to the first recipient and expecting its private note to remain intact. See [test results and reproduction](TEST-RESULTS.md). Independent multiple-recipient, fee and coin-control scenarios pass, so their evidence is retained separately.','',
'[Builds, capture method and limitations](PROVENANCE.md) · [Full test results](TEST-RESULTS.md) · [Machine-readable coverage](coverage.json) · [Capture hashes](selected-captures.json) · [Evidence integrity checks](logs/evidence-validation.json)','',
'## How to review','','1. Open a feature group and compare the two applications’ captures. Open an image to inspect it at full size.\n2. Read each subfeature’s stated assertion scope. A screenshot of a control does not prove clipboard contents, persistence, signing, or a successful operation.\n3. Follow the modules and test logs when deciding acceptance. Record acceptance only for the behavior and variants the evidence supports.','',
'## Feature groups','','| Group | Criteria | Widgets captures | QML captures | Evidence page |','| --- | ---: | ---: | ---: | --- |']
for f in features:
    counts={app:sum(p['application']==app and any(s.startswith(f['id']+'.') for s in p.get('features',[])) for p in photos) for app in ['widgets','qml']}
    lines.append(f'| {f["id"]} · {f["name"]} | {len(f["subfeatures"])} | {counts["widgets"]} | {counts["qml"]} | [Review](features/{f["slug"]}.md) |')
lines += ['','Counts are capture references, not counts of accepted criteria. A capture may support more than one criterion or group. A zero means no suitable capture was collected; consult that page for the implementation gap or remaining test.','',
'## Evidence boundaries','','- Linux X11 virtual desktops and synthetic regtest wallets only. No mainnet funds or personal wallet data.\n- Physical hardware-wallet approval, macOS Dock/App Nap, Windows session shutdown, router mapping, live Tor routing, and full mainnet synchronization remain outside this run.\n- Several broad criteria contain multiple variants. The pages explicitly preserve gaps such as untested Widgets multisig exchange, legacy migration captures, and rescan progress/cancellation.\n- QML watch-only export, desktop notifications and privacy mode remain implementation gaps.\n- The binaries use different pinned Core revisions and Qt builds. This evidence compares user capabilities; it is not a claim of identical backend or rendering behavior.','',
'## Collected material','','- `features/`: acceptance pages, grouped at the same level as the original inventory.\n- `media/`: original application-window and desktop screenshots, including raw checkpoints beyond the selected review set.\n- `logs/`: test output, assertions, bridge traces, build logs and desktop notification delivery.\n- `scripts/`: capture wrappers, independent scenarios, catalogue mappings and validators.\n- `inventory.json`, `coverage.json`, `summary.json`, `selected-captures.json`, `test-results.json`: traceable records for later updates.']
(ROOT/'README.md').write_text('\n'.join(lines)+'\n')
lines=['# Test results','','All results below are from this evidence collection on October 8, 2026. [Back to the evidence index](README.md).','',
'## Existing automated suites','','| Suite | Passed | Failed | Skipped | Result |','| --- | ---: | ---: | ---: | --- |']
for name,data in qtest.items():lines.append(f'| {name} | {data["passed"]} | {data["failed"]} | {data["skipped"]} | [Log](logs/{name}.log), exit {data["exit_code"]} |')
lines += ['','QTest totals include initialization, cleanup, and data-driven cases; they are not counts of independent end-user capabilities. The Widgets suite contains AppTests, OptionTests, URITests, RPCNestedTests, WalletTests and AddressBookTests. The [individual QTest outcomes](test-results.json) preserve case names.','',
'The first root run skipped a filesystem-permission unit test. The final non-root C++ run passed all 766 outcomes without skips. An initial functional wallet-load error test also failed under root; it passed as an ordinary user with the intended permission-denied fixture.','',
'## GUI-QML functional scripts','','| Script | Final result | Seconds | Captures |','| --- | --- | ---: | ---: |']
for r in sorted(functional,key=lambda r:r['test']):lines.append(f'| `{r["test"]}` | [{r["status"]}]({r["log"]}) | {r["seconds"]} | {r["captures"]} |')
lines += ['','The final functional manifest has 33 passes and one failure, with no silently accepted fixture skips. [`qml_test_wallet_qt_compat`](logs/qml_test_wallet_qt_compat.log) was run with `BITCOIN_QT_COMPAT` pointing to the pinned Widgets build in this comparison. Although the script’s default lookup says “31.0”, this is **not** a Bitcoin Core 31.0 release-binary certification. Legacy migration/restore uses an official checksummed Bitcoin Core 28.0 fixture.','',
'## Unresolved failure','','`qml_test_send_create` fails at its assertion that `sendNoteInput` still contains `My private note` after editing the first recipient again. This reproduced with the capture wrapper in both initial and non-root runs. The assertion is in [qml_test_send_create.py at the tested revision](https://github.com/bitcoin-core/gui-qml/blob/a91f4b4774f25de061fe1a7c132a91ddde117fca/test/functional/qml_test_send_create.py#L59).','',
'```bash\n# Inside the documented evidence container/mounts:\nDISPLAY=:94 BITCOIN_CORE_APP=/validation/build/bin/bitcoin-core-app \\\nBITCOIND=/tools/bitcoind TMPDIR=/work/tmp \\\npython3 /evidence/scripts/qml_capture_test.py \\\n  /work/qml-source/test/functional/qml_test_send_create.py\n```','',
'No product fix or assertion suppression was applied. The failure does not by itself establish the root cause. [The independent scenario](scripts/qml_additional.py) covers multi-recipient/custom-fee setup and coin selection/locking without passing through that failed note-restoration step.','',
'## Capture-driver adjustments','','The original onboarding scripts click the cover button before its delayed footer becomes enabled. The capture wrapper now waits for that real enabled state; the application and upstream assertions are unchanged. Both onboarding scripts then passed. It also allows a rendered frame after transitions before capturing.','',
'The external Widgets driver was brought up against actual control names and the current RPC schema. Setup issues included checkbox hit regions, URI address case, rich-text success messages, active-wallet selection, and PSBT v2 decoding. Final mapped assertions were rerun after correcting those expectations/selectors. Raw bridge traces include setup and repeat attempts; only the final assertions below are counted.','',
'## Additional live assertions','','| Application | Scenario | Passed | Failed | Evidence |','| --- | --- | ---: | ---: | --- |']
for app,name,rows,log,data in [('Widgets','GUI controls plus RPC/file/clipboard checks',widgets,'logs/widgets-bridge.jsonl','logs/widgets-checks.json'),('QML','Independent wallet/coin controls',extra,'logs/qml-additional.log','logs/qml-additional-checks.json'),('QML','Native Linux tray and exit',shell,'logs/qml-native-shell.log','logs/qml-native-shell-checks.json')]:
    lines.append(f'| {app} | {name} | {sum(r["status"]=="passed" for r in rows)} | {sum(r["status"]!="passed" for r in rows)} | [Log]({log}), [assertions]({data}) |')
lines += ['', 'Widgets native tray Exit and wallet-disabled shutdown returned exit 0. QML native tray Quit returned exit 0. The [notification daemon log](logs/widgets-notifications.log) independently records the incoming notification’s application name, amount, wallet and label.','',
'## Coverage not claimed','','This is release-build functional evidence. No production checkout was edited. Repository lint, clang-tidy, ASan/LSan/UBSan, TSan/MSan, ancestor-commit validation, and IPC-enabled `interface_gui.py` were not run for this documentation/capture task. These logs do not establish those CI passes. Both application builds have IPC disabled. The scripts and generated evidence are checked separately for syntax, links, criterion completeness, image integrity and capture hashes. See [evidence integrity results](logs/evidence-validation.json).']
(ROOT/'TEST-RESULTS.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(summary,indent=2))
